def solve(n, a, b, c):
    p = [0] * n
    p[0] = a[0]
    used = {p[0]}

    for i in range(1, n):
        if i == n - 1:
            for value in [a[i], b[i], c[i]]:
                if value not in used:
                    p[i] = value
                    break
        else:
            for value in [a[i], b[i], c[i]]:
                if value not in used:
                    p[(i + 1) % n] = value
                    used.add(value)
                    break

    return p

